package com.basics;

public class ifstatement {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int i =10;
		int j=50;
		if(i>j) {
			System.out.println("True");
		}
		else if(j>i){
			System.out.println("False");
		}
		else {
			System.out.println("Nothing");
		}
	}

}
